import { existsSync, readdirSync, readFileSync } from "node:fs";
import { fileURLToPath } from "node:url";
import { dirname, join } from "node:path";

const here = dirname(fileURLToPath(import.meta.url));
const seedPath = join(here, "../../data/pf2e/skill-actions.json");
const generatedDir = join(here, "../../data/pf2e/generated");

/** Unified rule record (generated by `npm run data:pf2e` or from the seed). */
export interface RuleRecord {
  name: string;
  category: string;
  traits?: string[];
  level?: number | null;
  rarity?: string | null;
  text: string;
  source: string;
  /** Foundry actionType: "action" | "reaction" | "free" | "passive" (absent in seed/old data). */
  actionType?: string | null;
  /** Number of actions (1|2|3) when actionType is "action". */
  actionCost?: number | null;
  /** Use limit ("once per round/day"): per is "round"|"turn"|"day"|ISO-8601 ("PT1H"). */
  frequency?: { max: number; per: string };
  /** Weapons (incl. alchemical bombs): structured damage from the Foundry doc. */
  damage?: { dice: number; die: string; type: string };
  /** Built-in persistent damage (e.g. alchemist's fire). */
  persistent?: { number: number; faces: number | null; type: string };
  /** Splash damage value, when > 0. */
  splash?: number;
  /** Item bonus to attack rolls, when != 0. */
  bonus?: number;
  /** Range in feet for thrown/ranged weapons. */
  range?: number;
  /** Weapon proficiency category: "simple" | "martial" | "advanced" | "unarmed". */
  weaponCategory?: string;
  /** Creatures (bestiary): structured statblock — real AC/HP/saves/attacks.
   *  Present only when the importer resolved AC and HP (honest absence). */
  statblock?: CreatureStatblock;
  /** Spells: structured mechanics (cast time, save/attack, damage, heighten). */
  spell?: SpellMechanics;
  /** Foundry `_id` — resolves selfEffect/GrantItem/@UUID (last segment). */
  uuid?: string;
  /** Original Foundry document type ("ammo" inside equipment, etc.). */
  docType?: string;
  /** Source pack directory under packs/. */
  pack?: string;
  /** `system.rules` VERBATIM — declarative rule elements (FlatModifier…).
   *  Import is total; consumption is incremental (ADR-007). */
  rules?: unknown[];
  /** Feats: NATIVE taxonomy (system.category): class|ancestry|classfeature|skill|… */
  featCategory?: string;
  /** Feats: declared prerequisites. */
  prerequisites?: string[];
  /** Feats: uuid of the effect carrying the usage mechanics. */
  selfEffect?: string;
  /** Feats: subfeatures verbatim (granted proficiencies, keyOptions…). */
  subfeatures?: unknown;
  /** Conditions: takes a numeric value? (frightened 2). */
  conditionValued?: boolean;
  /** Conditions: group + conditions this one overrides. */
  conditionGroup?: string;
  overrides?: string[];
  /** Effects: structured duration + badge (counter) verbatim. */
  effectDuration?: unknown;
  badge?: unknown;
  /** Hazards: stealth DC, complexity, disable/routine/reset prose. */
  hazard?: {
    stealth: number | null;
    isComplex: boolean;
    disable?: string;
    routine?: string;
    reset?: string;
  };
}

/** An NPC Strike (Foundry "melee" item — ranged attacks included). */
export interface CreatureAttack {
  name: string;
  /** Attack bonus (system.bonus.value). */
  bonus: number;
  /** Damage entries in statblock order; category "persistent" preserved for PR2. */
  damage: { formula: string; type: string; category?: string }[];
  traits: string[];
  /** Present when the strike is ranged (system.range.increment). */
  rangeIncrement?: number;
  /** attackEffects (grab, knockdown…) — stored, not yet enforced. */
  effects?: string[];
}

/** An NPC ability ("action" item: passives, reactions, special actions). */
export interface CreatureAbility {
  name: string;
  actionType: string; // "action" | "reaction" | "free" | "passive"
  actions: number | null;
  text: string;
  /** Traços da habilidade — fonte dos roll options `item:trait:*`. */
  traits?: string[];
  frequency?: { max: number; per: string };
}

/** An NPC spellcasting entry (DC/attack + granted spell list). */
export interface CreatureSpellcasting {
  name: string;
  tradition: string;
  type: string; // "prepared" | "spontaneous" | "innate" | "focus"
  dc: number;
  attack: number;
  spells: { name: string; rank: number }[];
}

export interface CreatureStatblock {
  ac: number;
  hp: number;
  perception: number;
  saves: { fortitude: number; reflex: number; will: number };
  abilities?: Record<string, number>;
  speed?: { land: number; other: { type: string; value: number }[] };
  size?: string;
  senses?: string[];
  immunities?: string[];
  weaknesses?: { type: string; value: number }[];
  resistances?: { type: string; value: number }[];
  attacks: CreatureAttack[];
  abilitiesList: CreatureAbility[];
  spellcasting?: CreatureSpellcasting[];
}

/** Structured spell mechanics (generated by the importer for "spell" docs). */
export interface SpellMechanics {
  /** Base rank; cantrips have rank 1 + `cantrip: true` (auto-heightened). */
  rank: number;
  cantrip: boolean;
  /** Raw cast time: "1" | "2" | "3" | "1 to 3" | "reaction" | "1 minute"… */
  castActions: string;
  /** Spell attack roll vs AC ("attack" trait). */
  attack: boolean;
  /** Target's save; basic = half damage on success. */
  defense?: { save: string; basic: boolean };
  damage: { formula: string; type: string; kinds: string[]; category?: string }[];
  /** Interval heightening: add `add[i]` to `damage[i]` each `interval` ranks. */
  heighten?: { interval: number; add: string[] };
  range?: string;
  area?: string;
  targets?: string;
  duration?: string;
}

interface SeedAction {
  id: string;
  name: string;
  skill: string;
  summary: string;
  criticalSuccess?: string;
  success?: string;
  failure?: string;
  criticalFailure?: string;
}

let index: RuleRecord[] | null = null;
let byName: Map<string, RuleRecord> | null = null;
let sourceLabel = "seed";

function normalize(s: string): string {
  return s
    .toLowerCase()
    .normalize("NFD")
    .replace(/[̀-ͯ]/g, "")
    .trim();
}

function loadSeed(): RuleRecord[] {
  try {
    const data = JSON.parse(readFileSync(seedPath, "utf8")) as {
      actions: SeedAction[];
    };
    return data.actions.map((a) => ({
      name: a.name,
      category: "actions",
      text: [
        a.summary,
        a.criticalSuccess ? `Critical success: ${a.criticalSuccess}` : "",
        a.success ? `Success: ${a.success}` : "",
        a.failure ? `Failure: ${a.failure}` : "",
        a.criticalFailure ? `Critical failure: ${a.criticalFailure}` : "",
      ]
        .filter(Boolean)
        .join(" "),
      source: "seed",
    }));
  } catch {
    return [];
  }
}

/**
 * Política de ÍNDICE POR NOME, em código — não por acidente da ordem
 * alfabética dos arquivos no disco.
 *
 * `NAME_INDEX_ORDER` define quem entra no índice por nome exato e em que
 * precedência (primeiro-ganha em colisão). `FUZZY_CATEGORIES` define quem os
 * passes fuzzy do `lookupLocalRule` enxergam: as categorias novas do import
 * total (2.815 effects "Effect: X", heritages, pregens…) ficam FORA do fuzzy
 * de propósito — o `lookup_rule` do GM não pode mudar de comportamento porque
 * o dataset ficou completo. `macros` (código JS de UI do Foundry) não é regra:
 * não entra em índice nenhum, só existe no dataset por completude.
 */
const NAME_INDEX_ORDER: readonly string[] = [
  // legado, na mesma precedência que a ordem alfabética antiga produzia:
  "actions",
  "bestiary",
  "conditions",
  "equipment",
  "feats",
  "spells",
  // novas categorias name-addressable (só nome EXATO, sem fuzzy — exceto hazards):
  "hazards",
  "effects",
  "ancestries",
  "heritages",
  "backgrounds",
  "classes",
  "deities",
  "campaign",
  "pregens",
  "vehicles",
  "armies",
  "familiars",
  "kits",
];
const FUZZY_CATEGORIES = new Set([
  "actions",
  "bestiary",
  "conditions",
  "equipment",
  "feats",
  "spells",
  "hazards",
]);

function loadGenerated(): RuleRecord[] {
  // Carga dirigida pelo manifest (importador v2): só as categorias declaradas
  // entram — um .json auxiliar largado na pasta (feats-classified.json) não
  // polui o índice POR CONSTRUÇÃO. Sem manifest (dataset antigo), cai no
  // comportamento legado de ler todo *.json com o filtro de completude.
  const manifestPath = join(generatedDir, "manifest.json");
  let files: string[];
  if (existsSync(manifestPath)) {
    try {
      const manifest = JSON.parse(readFileSync(manifestPath, "utf8")) as {
        categories?: Record<string, number>;
      };
      files = Object.keys(manifest.categories ?? {}).map((c) => `${c}.json`);
    } catch {
      files = [];
    }
  } else {
    files = readdirSync(generatedDir).filter(
      (f) => f.endsWith(".json") && f !== "uuid-index.json",
    );
  }
  const out: RuleRecord[] = [];
  for (const file of files) {
    try {
      const arr = JSON.parse(
        readFileSync(join(generatedDir, file), "utf8"),
      ) as RuleRecord[];
      out.push(
        ...arr.filter((r) => r && typeof r.name === "string" && r.category && r.text),
      );
    } catch {
      // ignore invalid file
    }
  }
  return out;
}

function load(): RuleRecord[] {
  if (index) return index;
  if (existsSync(generatedDir)) {
    index = loadGenerated();
    sourceLabel = `foundry-generated (${index.length} entries)`;
  }
  if (!index || index.length === 0) {
    index = loadSeed();
    sourceLabel = "seed (run `npm run data:pf2e` for the full dataset)";
  }
  byName = new Map();
  const rank = new Map(NAME_INDEX_ORDER.map((c, i) => [c, i]));
  // Precedência POR CATEGORIA (não por ordem de arquivo): estável e auditável.
  const indexable = index
    .filter((r) => rank.has(r.category))
    .sort((a, b) => rank.get(a.category)! - rank.get(b.category)!);
  for (const r of indexable) {
    const key = normalize(r.name);
    // Keep the first (avoids overwriting with same-named variants).
    if (!byName.has(key)) byName.set(key, r);
  }
  return index;
}

/**
 * Looks up a rule by name (any category). Strategy: exact name → substring →
 * highest token overlap. Returns the best match or `null`.
 */
export function lookupLocalRule(query: string): RuleRecord | null {
  const all = load();
  const q = normalize(query);
  if (!q) return null;

  // 1. Exact name.
  const exact = byName!.get(q);
  if (exact) return exact;

  // 2. Substring (prefers the shortest name = most specific match).
  // Fuzzy só nas categorias da política — as categorias novas do import total
  // não podem mudar o que o GM encontra por aproximação.
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const r of all) {
    if (!FUZZY_CATEGORIES.has(r.category)) continue;
    const n = normalize(r.name);
    if (n.includes(q) || q.includes(n)) {
      if (n.length < bestLen) {
        best = r;
        bestLen = n.length;
      }
    }
  }
  if (best) return best;

  // 3. Token overlap.
  const qTokens = new Set(q.split(/\s+/).filter((t) => t.length > 2));
  if (qTokens.size === 0) return null;
  let bestScore = 0;
  for (const r of all) {
    if (!FUZZY_CATEGORIES.has(r.category)) continue;
    const nTokens = normalize(r.name).split(/\s+/);
    let score = 0;
    for (const t of nTokens) if (qTokens.has(t)) score++;
    if (score > bestScore) {
      bestScore = score;
      best = r;
    }
  }
  return bestScore > 0 ? best : null;
}

export function datasetSource(): string {
  load();
  return sourceLabel;
}

let activityCosts: Map<string, number> | null = null;

/**
 * Detects a MULTI-action activity (feat/action, actionType "action", cost ≥ 2)
 * mentioned inside free text (a roll's reason). Returns its canonical
 * lowercase name and cost, or null. Used by the engine to charge an
 * activity's FULL cost even when the model forgets to pass it — the model
 * naming the activity in `reason` is far more reliable than it passing a
 * separate cost argument. Names < 6 chars are skipped (false-positive prone).
 */
export function multiActionCost(
  text: string,
): { name: string; cost: number } | null {
  if (!activityCosts) {
    activityCosts = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.actionType === "action" &&
        (r.actionCost ?? 0) >= 2 &&
        r.name.length >= 6
      ) {
        activityCosts.set(r.name.toLowerCase(), r.actionCost!);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, cost] of activityCosts) {
    if (t.includes(name)) return { name, cost };
  }
  return null;
}

let equipmentByName: Map<string, RuleRecord> | null = null;

/** Strips rune/quality prefixes so "+1 Striking Dagger" matches "Dagger". */
function baseItemName(name: string): string {
  return normalize(
    name.replace(/^\+\d+\s+/, "").replace(/^(striking|greater striking|major striking)\s+/i, ""),
  );
}

/**
 * Finds an equipment record by item name (exact → rune-stripped → the dataset
 * variant convention "Name (Lesser)" → substring). Backbone of the engine's
 * item grounding: traits, real damage, splash, range all come from here.
 */
export function itemRecord(name: string): RuleRecord | null {
  if (!equipmentByName) {
    equipmentByName = new Map();
    for (const r of load()) {
      if (r.category !== "equipment") continue;
      const key = normalize(r.name);
      if (!equipmentByName.has(key)) equipmentByName.set(key, r);
    }
  }
  const q = baseItemName(name);
  if (!q) return null;
  const exact = equipmentByName.get(q) ?? equipmentByName.get(normalize(name));
  if (exact) return exact;
  // Variant convention: consumables come as "Alchemist's Fire (Lesser)" etc.
  // A bare "alchemist's fire" should hit the weakest variant.
  for (const variant of ["lesser", "minor", "moderate", "greater", "major"]) {
    const v = equipmentByName.get(`${q} (${variant})`);
    if (v) return v;
  }
  // Substring, preferring the shortest (most specific) name.
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const [n, r] of equipmentByName) {
    if ((n.includes(q) || q.includes(n)) && n.length < bestLen) {
      best = r;
      bestLen = n.length;
    }
  }
  return best;
}

/** Traits of an equipment item (empty when unknown). */
export function itemTraits(name: string): string[] {
  return itemRecord(name)?.traits ?? [];
}

let frequencies: Map<string, { max: number; per: string }> | null = null;

/**
 * Use-limit of a feat/action mentioned in free text ("Frequency once per
 * round"), keyed the same way as `multiActionCost`: the model naming the
 * activity in `reason`/`skill` is the trigger. Names < 6 chars are skipped.
 */
export function activityFrequency(
  text: string,
): { name: string; max: number; per: string } | null {
  if (!frequencies) {
    frequencies = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.frequency &&
        r.name.length >= 6
      ) {
        const key = r.name.toLowerCase();
        if (!frequencies.has(key)) frequencies.set(key, r.frequency);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, f] of frequencies) {
    if (t.includes(name)) return { name, ...f };
  }
  return null;
}

let activeNames: Map<string, string> | null = null;

/**
 * An ACTIVE feat/action (actionType "action", cost ≥ 1) named inside free
 * text — used by the engine to notice the player invoked something with
 * rules that the model resolved as pure narration (Goblin Song case).
 * Returns the canonical name, or null. Names < 6 chars are skipped.
 */
export function namedActivity(text: string): string | null {
  if (!activeNames) {
    activeNames = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.actionType === "action" &&
        (r.actionCost ?? 0) >= 1 &&
        r.name.length >= 6
      ) {
        const key = r.name.toLowerCase();
        if (!activeNames.has(key)) activeNames.set(key, r.name);
      }
    }
  }
  const t = text.toLowerCase();
  for (const [key, name] of activeNames) {
    if (t.includes(key)) return name;
  }
  return null;
}

let basicActionNames: string[] | null = null;

/**
 * A AÇÃO básica citada em prosa livre ("Climb the wall" → "Climb"), para o
 * vocabulário `action:*` das roll options (Fase 2.5 / T5.4).
 *
 * Existe separado de `namedActivity` porque aquele serve a outro propósito —
 * cobrar o custo de atividades de várias ações — e por isso exige nome com 6+
 * caracteres, o que exclui justamente as ações básicas que os rule elements
 * mais testam (`Climb`, `Trip`, `Shove`, `Hide`, `Seek`).
 *
 * Só a categoria `actions` entra, e só com nome de 4+ letras casado por palavra
 * inteira, preferindo o mais longo. Um falso positivo aqui não fabrica número
 * nenhum sozinho: ele apenas TORNA DECIDÍVEL um predicado que sem isso ficaria
 * indecidível — e indecidível já não aplica.
 */
export function mentionedAction(text: string): string | null {
  if (!basicActionNames) {
    basicActionNames = load()
      .filter((r) => r.category === "actions" && r.name.length >= 4 && /^[A-Za-z' -]+$/.test(r.name))
      .map((r) => r.name)
      .sort((a, b) => b.length - a.length);
  }
  const t = text.toLowerCase();
  for (const name of basicActionNames) {
    const escaped = name.toLowerCase().replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    if (new RegExp(`\\b${escaped}\\b`).test(t)) return name;
  }
  return null;
}

let requirementTexts: Map<string, string> | null = null;

/**
 * Requirements clause of a feat/action named in free text ("Requirements You
 * are wielding two melee weapons."). Same trigger convention as
 * `multiActionCost`: the model naming the activity. The engine validates only
 * a small whitelist of patterns it can answer from the sheet.
 */
export function activityRequirement(
  text: string,
): { name: string; requirement: string } | null {
  if (!requirementTexts) {
    requirementTexts = new Map();
    for (const r of load()) {
      if (
        (r.category === "feats" || r.category === "actions") &&
        r.name.length >= 6 &&
        r.actionType &&
        r.actionType !== "passive"
      ) {
        const m = /Requirements\s+([^.;]+)[.;]/.exec(r.text);
        if (m?.[1]) {
          const key = r.name.toLowerCase();
          if (!requirementTexts.has(key)) requirementTexts.set(key, m[1].trim());
        }
      }
    }
  }
  const t = text.toLowerCase();
  for (const [name, requirement] of requirementTexts) {
    if (t.includes(name)) return { name, requirement };
  }
  return null;
}

/** Custo de uso de um feat/ação, na taxonomia real do PF2e. */
export interface CostProfile {
  /** Nome canônico do registro. */
  name: string;
  /** `action` gasta ações; `reaction` gasta A reação; `free` e `passive` não gastam nada. */
  kind: "action" | "reaction" | "free" | "passive";
  /** Ações gastas — só é > 0 quando `kind === "action"`. */
  cost: number;
}

let byNameAll: Map<string, RuleRecord[]> | null = null;

/** Todos os registros que compartilham um nome (em qualquer categoria). */
function recordsNamed(name: string): RuleRecord[] {
  if (!byNameAll) {
    byNameAll = new Map();
    for (const r of load()) {
      if (r.category === "macros") continue; // código de UI, não regra
      const key = normalize(r.name);
      const list = byNameAll.get(key);
      if (list) list.push(r);
      else byNameAll.set(key, [r]);
    }
  }
  return byNameAll.get(normalize(name)) ?? [];
}

/**
 * Homônimos de um registro — os OUTROS registros com o mesmo nome.
 *
 * O índice principal é primeiro-ganha por ordem alfabética de arquivo, então
 * servir só o vencedor esconde dado do modelo (doutrina: o dado não se
 * esconde). Quem consulta mostra os dois e deixa o modelo escolher.
 */
export function homonymsOf(rec: RuleRecord): RuleRecord[] {
  return recordsNamed(rec.name).filter(
    (r) => r !== rec && r.category !== rec.category,
  );
}

/** Rótulo curto do custo de uso, para o texto que o modelo lê. */
export function actionLabel(rec: RuleRecord): string {
  if (rec.actionType === "reaction") return "reaction";
  if (rec.actionType === "free") return "free action";
  if (rec.actionType === "action") {
    const n = Math.max(1, rec.actionCost ?? 1);
    return `${n} action${n > 1 ? "s" : ""}`;
  }
  if (rec.actionType === "passive") return "passive";
  return "";
}

/**
 * Perfil de custo de um feat/ação pelo NOME EXATO.
 *
 * Por que `prefer`: o índice por nome do `load()` é primeiro-ganha na ordem
 * alfabética dos arquivos, então `actions.json` ofusca `feats.json` em todo
 * homônimo. "Shake it Off" existe nos dois — ação de REAÇÃO [fortune, primal]
 * e feat de bárbaro de 1 AÇÃO — e o lookup genérico servia a reação, fazendo a
 * engine cobrar zero pelo feat (bateria 2026-07-24). Quem desempata é a ficha:
 * se o personagem TEM o feat, a categoria `feats` manda.
 *
 * Por que custo CONCRETO ganha de `passive`: a varredura de conformidade achou
 * 44 nomes com custo divergente, e em 34 deles o registro de `feats` é
 * `passive` porque o feat apenas CONCEDE a habilidade — a mecânica real (e o
 * custo) vive no registro de `actions` com o mesmo nome (Hunt Prey, Change
 * Shape, Arcane Cascade, Opportune Riposte…). Preferir cegamente a ficha ali
 * devolveria "passivo, custo zero" para atividades de 1-2 ações e faria 7
 * reações jamais debitarem a reação. `passive` só vence quando é a única forma
 * que existe.
 */
export function costProfileOf(
  name: string,
  prefer: "feats" | "actions" = "feats",
): CostProfile | null {
  const candidates = recordsNamed(name).filter(
    (r) => r.category === "feats" || r.category === "actions",
  );
  if (!candidates.length) return null;
  const concrete = (r: RuleRecord) =>
    r.actionType === "action" || r.actionType === "reaction" || r.actionType === "free";
  const preferred = candidates.find((r) => r.category === prefer);
  const rec =
    preferred && concrete(preferred)
      ? preferred
      : (candidates.find(concrete) ?? preferred ?? candidates[0]!);
  const kind: CostProfile["kind"] =
    rec.actionType === "action" ||
    rec.actionType === "reaction" ||
    rec.actionType === "free"
      ? rec.actionType
      : "passive";
  return {
    name: rec.name,
    kind,
    cost: kind === "action" ? Math.max(1, rec.actionCost ?? 1) : 0,
  };
}

let creaturesByName: Map<string, RuleRecord> | null = null;

/**
 * Normalizes a combatant/creature name into a bestiary query: drops the
 * engine's instance suffix ("Goblin Warrior 2"), parentheticals
 * ("Rat Swarm (Large)") and extra whitespace.
 */
function normalizeCreatureQuery(name: string): string {
  return normalize(name.replace(/\([^)]*\)/g, " ").replace(/\s+\d+\s*$/, ""))
    .replace(/\s+/g, " ")
    .trim();
}

function escapeRegex(s: string): string {
  return s.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
}

/** Whole-word containment: "giant rat" inside "ancient giant rat", not "rate". */
function wordBounded(hay: string, needle: string): boolean {
  return new RegExp(`(^|\\s)${escapeRegex(needle)}(\\s|$)`).test(hay);
}

/**
 * Finds a bestiary record WITH a structured statblock by creature name.
 * Strategy: exact → model-plural ("Giant Rats") → record name contained
 * whole-word in the query ("elite Goblin Warrior" → Goblin Warrior; shortest
 * wins). The REVERSE direction is deliberately not matched: a generic "Thug"
 * must never bind to a specific "Scarlet Triad Thug" (level 7) — unknown
 * names fall back to the level benchmark. Never matches across categories.
 */
export function creatureRecord(name: string): RuleRecord | null {
  if (!creaturesByName) {
    creaturesByName = new Map();
    for (const r of load()) {
      if (r.category !== "bestiary" || !r.statblock) continue;
      const key = normalize(r.name);
      if (!creaturesByName.has(key)) creaturesByName.set(key, r);
    }
  }
  const q = normalizeCreatureQuery(name);
  if (!q) return null;

  const exact = creaturesByName.get(q);
  if (exact) return exact;

  // The model often pluralizes ("three Giant Rats").
  const singular = q.replace(/s$/, "");
  if (singular !== q) {
    const s = creaturesByName.get(singular);
    if (s) return s;
  }

  // Longest record name contained in the query wins (most specific:
  // "elite Goblin Warrior" must hit "Goblin Warrior", not a bare "Goblin").
  let best: RuleRecord | null = null;
  let bestLen = 0;
  for (const [n, r] of creaturesByName) {
    if (n.length > bestLen && wordBounded(q, n)) {
      best = r;
      bestLen = n.length;
    }
  }
  if (best) return best;

  // Last resort: same token count, each token equal OR sharing a ≥6-char
  // prefix — bridges morphology slips ("Skeleton Champion" → "Skeletal
  // Champion") without reopening the generic-name hole ("Thug" stays null).
  const qTokens = q.split(" ");
  for (const [n, r] of creaturesByName) {
    const nTokens = n.split(" ");
    if (nTokens.length !== qTokens.length) continue;
    const all = qTokens.every((qt, i) => {
      const nt = nTokens[i]!;
      if (qt === nt) return true;
      const shared = Math.min(qt.length, nt.length);
      return shared >= 6 && qt.slice(0, 6) === nt.slice(0, 6);
    });
    if (all) return r;
  }
  return null;
}

let spellsByName: Map<string, RuleRecord> | null = null;

/**
 * Finds a spell record WITH structured mechanics by name. Exact →
 * whole-word containment (shortest wins — spell names are specific).
 * Returns `null` when unknown; never matches across categories.
 */
export function spellRecord(name: string): RuleRecord | null {
  if (!spellsByName) {
    spellsByName = new Map();
    for (const r of load()) {
      if (r.category !== "spells" || !r.spell) continue;
      const key = normalize(r.name);
      if (!spellsByName.has(key)) spellsByName.set(key, r);
    }
  }
  const q = normalize(name).replace(/\s+/g, " ").trim();
  if (!q) return null;
  const exact = spellsByName.get(q);
  if (exact) return exact;
  let best: RuleRecord | null = null;
  let bestLen = Infinity;
  for (const [n, r] of spellsByName) {
    if (n.length < bestLen && (wordBounded(q, n) || wordBounded(n, q))) {
      best = r;
      bestLen = n.length;
    }
  }
  return best;
}

/**
 * Os registros da categoria `conditions`, sem fuzzy. `lookupLocalRule` casa por
 * substring nas categorias da política, e "prone" acabaria num feat de nome
 * parecido — quem consome rule element de condição precisa do exato.
 */
export function conditionRecords(): RuleRecord[] {
  return load().filter((r) => r.category === "conditions");
}

/**
 * Os registros de UMA categoria, sem fuzzy e sem a precedência do índice por
 * nome. Quem consome rule element precisa disso: "Shield Block" existe em
 * `actions` E em `feats`, e o índice global entrega o de `actions` (política
 * declarada em `NAME_INDEX_ORDER`). Para saber o que o FEAT da ficha faz, é
 * preciso olhar a categoria certa.
 */
export function categoryRecords(category: string): RuleRecord[] {
  return load().filter((r) => r.category === category);
}

let conditionNames: Set<string> | null = null;

/**
 * The official PF2e condition names (lowercase) from conditions.json — the
 * whitelist `update_state` validates against. Falls back to a hardcoded core
 * set when the generated dataset is absent (seed mode).
 */
export function officialConditions(): Set<string> {
  if (!conditionNames) {
    conditionNames = new Set(
      load()
        .filter((r) => r.category === "conditions")
        .map((r) => r.name.toLowerCase()),
    );
    if (conditionNames.size === 0) {
      conditionNames = new Set([
        "blinded", "clumsy", "concealed", "confused", "controlled", "dazzled",
        "deafened", "doomed", "drained", "dying", "encumbered", "enfeebled",
        "fascinated", "fatigued", "fleeing", "frightened", "grabbed", "hidden",
        "immobilized", "invisible", "off-guard", "paralyzed", "persistent damage",
        "petrified", "prone", "quickened", "restrained", "sickened", "slowed",
        "stunned", "stupefied", "unconscious", "wounded",
      ]);
    }
  }
  return conditionNames;
}

// ---------------------------------------------------------------------------
// Lookups do import total (Fase 1.5) — hazards, effects e o grafo de UUIDs.
// ---------------------------------------------------------------------------

let hazardsByName: Map<string, RuleRecord> | null = null;

/** Hazard (armadilha/perigo) por nome — mesmo espírito do creatureRecord. */
export function hazardRecord(name: string): RuleRecord | null {
  if (!hazardsByName) {
    hazardsByName = new Map();
    for (const r of load()) {
      if (r.category !== "hazards") continue;
      const key = normalize(r.name);
      if (!hazardsByName.has(key)) hazardsByName.set(key, r);
    }
  }
  return hazardsByName.get(normalize(name)) ?? null;
}

let uuidMap: Map<string, RuleRecord> | null = null;

/**
 * Resolve um documento pelo `_id` Foundry (aceita o UUID completo
 * "Compendium.pf2e.feat-effects.Item.XYZ" — usa o último segmento). É como
 * `selfEffect` e `GrantItem` chegam ao registro alvo.
 */
export function byUuid(ref: string): RuleRecord | null {
  if (!uuidMap) {
    uuidMap = new Map();
    for (const r of load()) {
      if (r.uuid && !uuidMap.has(r.uuid)) uuidMap.set(r.uuid, r);
    }
  }
  const id = ref.split(".").pop() ?? ref;
  return uuidMap.get(id) ?? null;
}

/** Effect por uuid OU nome exato (effects ficam fora do fuzzy de propósito). */
export function effectRecord(ref: string): RuleRecord | null {
  const viaUuid = byUuid(ref);
  if (viaUuid?.category === "effects") return viaUuid;
  const key = normalize(ref);
  for (const r of load()) {
    if (r.category === "effects" && normalize(r.name) === key) return r;
  }
  return null;
}
